import {on} from 'delegated-events'

on('click', '.js-manage-requests-tabs-item', function ({currentTarget}) {
  const container = currentTarget.closest<HTMLElement>('.js-manage-memberships-container')!
  container.querySelector<HTMLElement>('.js-manage-invitations-tabs-item')!.classList.remove('selected')
  currentTarget.classList.add('selected')

  const currentList = container.querySelector<HTMLElement>('.js-manage-invitations-list')!
  const targetList = container.querySelector<HTMLElement>('.js-manage-requests-list')!
  /* eslint-disable-next-line github/no-d-none */
  currentList.classList.add('d-none')
  /* eslint-disable-next-line github/no-d-none */
  targetList.classList.remove('d-none')
})

on('click', '.js-manage-invitations-tabs-item', function ({currentTarget}) {
  const container = currentTarget.closest<HTMLElement>('.js-manage-memberships-container')!
  container.querySelector<HTMLElement>('.js-manage-requests-tabs-item')!.classList.remove('selected')
  currentTarget.classList.add('selected')

  const currentList = container.querySelector<HTMLElement>('.js-manage-requests-list')!
  const targetList = container.querySelector<HTMLElement>('.js-manage-invitations-list')!
  /* eslint-disable-next-line github/no-d-none */
  currentList.classList.add('d-none')
  /* eslint-disable-next-line github/no-d-none */
  targetList.classList.remove('d-none')
})
